import{_ as t,H as a,f as o,i}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"每周一起背10句 | week 01","description":"","frontmatter":{},"headers":[],"relativePath":"互联网人的英语私教课/每周一起背10句-week01.md","filePath":"互联网人的英语私教课/每周一起背10句-week01.md","lastUpdated":1779817970000}'),p={name:"互联网人的英语私教课/每周一起背10句-week01.md"};function s(n,e,r,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="每周一起背10句-week-01" tabindex="-1">每周一起背10句 | week 01 <a class="header-anchor" href="#每周一起背10句-week-01" aria-label="Permalink to &quot;每周一起背10句 | week 01&quot;">​</a></h1><p>你好，我是英语专栏的编辑阿锦，欢迎来到第1期的“每周一起背10句”。</p><p>我们的陈老师说啦，语言学习有方法但无捷径。不论多少，每天听和读，贵在坚持。所以呢，为了帮助你真正吃透我们学过的内容，每周我都会从本周学过的句子中，抽选出10句非常棒的句子。</p><p>你可以熟读，直到背诵，然后把句子默写下来。同时，我在每句话里标出了我们的核心词，你可以用英语去形容一下这些词的意思，回想一下它的词组、搭配以及使用场景。如果有余力，也可以尝试用这些单词或词组来造句！</p><hr><p>例句1：The United States is a sports-minded country, with millions of fans who follow football, baseball, basketball and hockey, among other sports.</p><p>翻译：美国是一个体育意识很强的国家，有数以百万计的球迷关注足球、棒球、篮球和曲棍球等体育运动。</p><p>例句2：The difference between proactive people and reactive people is that proactive people take initiative, and they come up with ideas to get things done despite the conditions they are in. Reactive people, on the other hand, usually are the ones to react to a situation rather than take initiative to create a situation.</p><p>翻译：积极主动的人和消极被动的人之间的区别在于，积极主动的人会采取主动，无论他们所处的环境如何，都会想出办法来完成任务；而消极被动型的人通常只会对形势做出被动的反应，而不会主动采取行动去创造形势。</p><p>例句3：Don’t jump to conclusions! Perhaps it was his daughter he was dancing with.</p><p>翻译：别匆忙下结论，和他跳舞的没准是他女儿呢。</p><p>例句4：The workers approached the manager with a request for shorter working hours.</p><p>翻译：工人们找经理要求减少工作时间。</p><p>例句5：His sober approach to the crisis averted a catastrophe.</p><p>翻译：他对危机的冷静处理避免了一场大灾难。</p><p>例句6：They take the time to understand how the business works, how the product fits in, and what its goals are.</p><p>翻译：他们会花时间去了解企业是如何商业运作的，产品又是如何配合商业运作，以及最终要达到什么样的商业目标。</p><p>例句7：You need to work hard—opportunities don’t just come out of thin air.</p><p>翻译：你得努力啦，机会不会凭空产生（天上不会掉馅饼）。</p><p>例句8：He is empathetic with the jobless youth, as he was also struggling for a job in his early years.</p><p>翻译：他对失业的年轻人感同身受，因为他自己早年也为找工作挣扎过。</p><p>例句9：Social media technologies have given companies access to an unprecedented flood of new analytics, metrics and user data.</p><p>翻译：有了社交网络之后，企业获取了空前大量的新分析方法、度量指标和用户数据。</p><p>例句10：Steve Jobs was a gifted communicator, and he used this skill to capture the attention of millions.</p><p>翻译：乔布斯是一个有天赋的沟通者，他用这种技巧吸引了数百万人的注意力。</p>',25)])])}const w=t(p,[["render",s]]);export{u as __pageData,w as default};
